window.GCAM_DIAGRAMS = {"hero": {"title": "Scientific machine learning and Physical AI", "caption": "Physics gives structure and data give detail; scientific machine learning combines them into models that are accurate, fast and honest about uncertainty, and Physical AI puts them to work in transport.", "nodes": [{"id": "phy", "label": "Physical laws", "sub": "equations we trust", "x": 140, "y": 90, "w": 200, "h": 64, "sys": "energy", "detail": {"1": "Laws such as conservation of vehicles, Newton's laws and energy balances. They hold even where we have no data.", "2": "ODEs and PDEs: the LWR traffic model, car-following models, the road-load equation. Solved by classical solvers or used as residuals in learning.", "3": "Research angle: which parts of the physics are trusted, and which need learning? That choice shapes every SciML design."}}, {"id": "dat", "label": "Data", "sub": "sensors, video, simulations", "x": 140, "y": 260, "w": 200, "h": 64, "sys": "water", "detail": {"1": "Measurements from detectors, GPS, cameras and experiments, and outputs of simulators.", "2": "Noisy, sparse and biased towards normal conditions. Split honestly, look for leakage, and keep test data untouched.", "3": "Research angle: rare events (crashes, crushes, extreme weather) are where data are thinnest and physics matters most."}}, {"id": "ml", "label": "Machine learning", "sub": "networks, GPs, regression", "x": 140, "y": 430, "w": 200, "h": 64, "sys": "economy", "detail": {"1": "Flexible functions whose parameters are learned from examples by minimising a loss.", "2": "Neural networks, Gaussian processes and sparse regression, trained by gradient descent with automatic differentiation.", "3": "Research angle: physics-aware architectures and losses that keep learned models within physical limits."}}, {"id": "sci", "label": "Scientific ML", "sub": "PINNs, operators, hybrids", "x": 450, "y": 260, "w": 200, "h": 64, "sys": "economy", "detail": {"1": "Machine learning that respects physics.", "2": "Physics-informed networks, equation discovery, neural operators, surrogates, hybrid models and data assimilation.", "3": "Research angle: when does adding physics actually help? Ablations against strong baselines answer this."}}, {"id": "unc", "label": "Uncertainty", "sub": "how sure are we?", "x": 450, "y": 440, "w": 200, "h": 64, "sys": "climate", "detail": {"1": "Every prediction should say how sure it is.", "2": "Gaussian processes, ensembles and conformal prediction give intervals; calibration checks that they are honest.", "3": "Research angle: conditional coverage, rare events and decision-relevant uncertainty."}}, {"id": "pai", "label": "Physical AI", "sub": "sense, decide, act", "x": 760, "y": 160, "w": 200, "h": 64, "sys": "policy", "detail": {"1": "Machines that sense and act in the physical world: automated vehicles, robots, adaptive signals.", "2": "Estimation (Kalman filters), learned perception, model-based and learned control, with safety layers.", "3": "Research angle: verifying learned controllers and training them safely in digital twins."}}, {"id": "trn", "label": "Transport decisions", "sub": "safety, sustainability, operations", "x": 760, "y": 360, "w": 200, "h": 64, "sys": "policy", "detail": {"1": "Safer roads, lower emissions and smoother traffic.", "2": "Traffic estimation, car following, conflict analysis, emissions, GCAM emulators, crowd safety and digital twins.", "3": "Research angle: honest evaluation and fairness when models trained in one place are used in another."}}], "edges": [{"from": "phy", "to": "sci", "label": "structure"}, {"from": "dat", "to": "sci", "label": "detail"}, {"from": "ml", "to": "sci", "label": "flexibility"}, {"from": "sci", "to": "pai", "label": "models"}, {"from": "sci", "to": "trn", "label": "insight"}, {"from": "unc", "to": "trn", "label": "honesty", "sys": "climate"}, {"from": "sci", "to": "unc", "label": "quantified"}, {"from": "pai", "to": "dat", "label": "new data", "sys": "water"}], "tour": [{"focus": ["phy", "dat", "ml"], "text": "Three ingredients: physical laws, data, and machine learning."}, {"focus": ["sci"], "edges": [["phy", "sci"], ["dat", "sci"], ["ml", "sci"]], "text": "Scientific machine learning combines them: physics for structure, data for detail, learning for flexibility."}, {"focus": ["unc"], "edges": [["sci", "unc"]], "text": "Its predictions come with honest uncertainty."}, {"focus": ["pai"], "edges": [["sci", "pai"], ["pai", "dat"]], "text": "Physical AI puts the models into machines that sense and act, and they in turn produce new data."}, {"focus": ["trn"], "edges": [["sci", "trn"], ["unc", "trn"]], "text": "In transport, this supports safer, cleaner and smoother systems."}]}, "m1.1": {"title": "Two ways of knowing, and the bridge between them", "caption": "Physics gives structure, data gives detail; scientific machine learning combines them, and Physical AI acts on the result.", "nodes": [{"id": "phy", "label": "Physical laws", "sub": "conservation, motion, energy", "x": 140, "y": 110, "w": 170, "h": 64, "sys": "energy", "detail": "Equations we trust: conservation of mass and energy, Newton's laws, traffic-flow and heat equations. They hold everywhere, even where we have no data."}, {"id": "dat", "label": "Data", "sub": "sensors, experiments, logs", "x": 140, "y": 330, "w": 170, "h": 64, "sys": "water", "detail": "Measurements from sensors, cameras, simulations and experiments. Rich in detail, but noisy, incomplete and only where we looked."}, {"id": "sci", "label": "Scientific ML", "sub": "physics + learning", "x": 450, "y": 220, "w": 190, "h": 64, "sys": "economy", "detail": "Machine learning that respects physics: physics-informed networks, equation discovery, operator learning, hybrid models and surrogates."}, {"id": "mdl", "label": "Trustworthy model", "sub": "accurate, general, fast", "x": 760, "y": 110, "w": 170, "h": 64, "sys": "land", "detail": "A model that fits the data, obeys the laws, extrapolates sensibly and can run fast enough to use."}, {"id": "pai", "label": "Physical AI", "sub": "sense, decide, act", "x": 760, "y": 330, "w": 170, "h": 64, "sys": "policy", "detail": "Robots, drones, automated vehicles and smart infrastructure that use such models to act in the real world, safely."}, {"id": "unc", "label": "Uncertainty", "sub": "how sure are we?", "x": 450, "y": 440, "w": 170, "h": 64, "sys": "climate", "detail": "Every model is wrong somewhere. Knowing how wrong, and where, is what makes a model safe to use for decisions."}], "edges": [{"from": "phy", "to": "sci", "label": "structure"}, {"from": "dat", "to": "sci", "label": "detail"}, {"from": "sci", "to": "mdl", "label": "builds"}, {"from": "mdl", "to": "pai", "label": "drives"}, {"from": "pai", "to": "dat", "label": "new data", "sys": "water"}, {"from": "unc", "to": "mdl", "label": "qualifies", "sys": "climate"}], "tour": [{"focus": ["phy"], "text": "Physics: laws that hold everywhere, but only describe what we chose to model."}, {"focus": ["dat"], "text": "Data: rich detail, but only where and when we measured."}, {"focus": ["phy", "dat", "sci"], "text": "Scientific machine learning uses both: physics for structure, data for detail.", "edges": [["phy", "sci"], ["dat", "sci"]]}, {"focus": ["sci", "mdl"], "text": "The goal is a model that is accurate, general and fast.", "edges": [["sci", "mdl"]]}, {"focus": ["mdl", "pai"], "text": "Physical AI puts such models inside machines that sense and act.", "edges": [["mdl", "pai"], ["pai", "dat"]]}, {"focus": ["unc"], "text": "And every model must say how sure it is.", "edges": [["unc", "mdl"]]}]}, "m1.2": {"title": "From a rule for change to a prediction", "caption": "An equation gives the rate of change; a solver turns it into a trajectory; data check it.", "nodes": [{"id": "law", "label": "Law of change", "sub": "dy/dt = f(y, t)", "x": 140, "y": 110, "w": 170, "h": 64, "sys": "energy", "detail": "The equation: how fast y changes, given its current value. Decay: dy/dt = −k y. Growth with a limit: dy/dt = k y (1 − y)."}, {"id": "ic", "label": "Starting value", "sub": "y at t = 0", "x": 140, "y": 330, "w": 170, "h": 64, "sys": "water", "detail": "An initial condition. The same law gives different futures from different starts."}, {"id": "sol", "label": "Solver", "sub": "Euler, Runge–Kutta", "x": 450, "y": 220, "w": 170, "h": 64, "sys": "economy", "detail": "Step forward: y_next = y + Δt × f(y). Better solvers (Runge–Kutta) sample the slope several times per step."}, {"id": "traj", "label": "Trajectory", "sub": "y over time", "x": 760, "y": 110, "w": 170, "h": 64, "sys": "land", "detail": "The predicted path of the system over time."}, {"id": "dt", "label": "Step size Δt", "sub": "accuracy vs cost", "x": 450, "y": 440, "w": 170, "h": 64, "sys": "climate", "detail": "Smaller steps: more accurate, more work. Too large: errors grow, and some schemes blow up (instability)."}, {"id": "pde", "label": "PDEs", "sub": "change in space and time", "x": 760, "y": 330, "w": 170, "h": 64, "sys": "energy", "detail": "Partial differential equations: traffic density, heat, air pollution and fluid flow change along a road or through space as well as in time."}], "edges": [{"from": "law", "to": "sol", "label": ""}, {"from": "ic", "to": "sol", "label": ""}, {"from": "sol", "to": "traj", "label": "steps"}, {"from": "dt", "to": "sol", "label": "controls", "sys": "climate"}, {"from": "law", "to": "pde", "label": "extends to"}], "tour": [{"focus": ["law"], "text": "The equation is a rule for change, not a formula for the answer."}, {"focus": ["ic", "law", "sol"], "text": "With a starting value, a solver can follow the rule.", "edges": [["law", "sol"], ["ic", "sol"]]}, {"focus": ["sol", "traj"], "text": "Step by step it builds the trajectory.", "edges": [["sol", "traj"]]}, {"focus": ["dt"], "text": "The step size trades accuracy against cost.", "edges": [["dt", "sol"]]}, {"focus": ["pde"], "text": "When things change in space too, we get partial differential equations.", "edges": [["law", "pde"]]}]}, "m1.3": {"title": "Inside a small network", "caption": "Inputs flow through weighted sums and soft steps to an output; training adjusts the weights.", "nodes": [{"id": "in", "label": "Input x", "sub": "e.g. time, density", "x": 120, "y": 220, "w": 170, "h": 64, "sys": "water", "detail": "The numbers we feed in: time, position, traffic density, temperature."}, {"id": "w", "label": "Weights and biases", "sub": "the adjustable knobs", "x": 420, "y": 80, "w": 170, "h": 64, "sys": "economy", "detail": "Every connection has a weight; every neuron a bias. A network with 10 hidden neurons and one input has 31 of them."}, {"id": "hid", "label": "Hidden neurons", "sub": "tanh(w·x + b)", "x": 420, "y": 220, "w": 170, "h": 64, "sys": "economy", "detail": "Each neuron makes a soft step whose position and steepness depend on its weight and bias."}, {"id": "out", "label": "Output", "sub": "weighted sum", "x": 720, "y": 220, "w": 170, "h": 64, "sys": "land", "detail": "The output adds the hidden neurons' values with output weights. More neurons, more possible shapes."}, {"id": "loss", "label": "Loss", "sub": "how wrong?", "x": 720, "y": 400, "w": 170, "h": 64, "sys": "climate", "detail": "Compares outputs with the data, e.g. the mean squared error. Training lowers it."}, {"id": "data", "label": "Training data", "sub": "examples (x, y)", "x": 420, "y": 400, "w": 170, "h": 64, "sys": "water", "detail": "Pairs of inputs and correct outputs. The network only knows what these examples show."}], "edges": [{"from": "in", "to": "hid", "label": ""}, {"from": "w", "to": "hid", "label": "set"}, {"from": "hid", "to": "out", "label": "sum"}, {"from": "out", "to": "loss", "label": ""}, {"from": "data", "to": "loss", "label": "compare"}, {"from": "loss", "to": "w", "label": "adjust", "sys": "climate"}], "tour": [{"focus": ["in", "hid"], "text": "An input passes into the hidden neurons.", "edges": [["in", "hid"]]}, {"focus": ["hid", "w"], "text": "Each neuron computes a weighted sum and squashes it with tanh: a soft step.", "edges": [["w", "hid"]]}, {"focus": ["out"], "text": "The output adds up the soft steps with new weights.", "edges": [["hid", "out"]]}, {"focus": ["loss", "data"], "text": "The loss measures how far the output is from the data.", "edges": [["out", "loss"], ["data", "loss"]]}, {"focus": ["w"], "text": "Training changes the weights to lower the loss.", "edges": [["loss", "w"]]}]}, "m1.4": {"title": "The training loop", "caption": "Predict, measure the loss, compute gradients by automatic differentiation, update the weights, repeat.", "nodes": [{"id": "pred", "label": "Predict", "sub": "model output", "x": 140, "y": 110, "w": 170, "h": 64, "sys": "land", "detail": "Run the model on training inputs to get predictions."}, {"id": "loss", "label": "Loss", "sub": "one number: how wrong", "x": 450, "y": 110, "w": 170, "h": 64, "sys": "climate", "detail": "For example mean squared error, (1/N) Σ (prediction − data)². Physics terms can be added (module 1.5)."}, {"id": "grad", "label": "Gradient", "sub": "which way is downhill", "x": 760, "y": 220, "w": 170, "h": 64, "sys": "economy", "detail": "The vector of partial derivatives of the loss with respect to every weight."}, {"id": "ad", "label": "Automatic differentiation", "sub": "chain rule, exactly", "x": 760, "y": 420, "w": 200, "h": 64, "sys": "economy", "detail": "Software (PyTorch, JAX) records each operation and applies the chain rule backwards to get exact gradients."}, {"id": "upd", "label": "Update", "sub": "w ← w − η × gradient", "x": 450, "y": 330, "w": 170, "h": 64, "sys": "economy", "detail": "Take a step downhill. η is the learning rate. Momentum and Adam modify this step."}, {"id": "w", "label": "Weights", "sub": "the knobs", "x": 140, "y": 330, "w": 170, "h": 64, "sys": "water", "detail": "The adjustable parameters. After many updates they settle in a valley of the loss."}], "edges": [{"from": "pred", "to": "loss", "label": ""}, {"from": "loss", "to": "grad", "label": ""}, {"from": "ad", "to": "grad", "label": "computes"}, {"from": "grad", "to": "upd", "label": ""}, {"from": "upd", "to": "w", "label": ""}, {"from": "w", "to": "pred", "label": "next pass"}], "tour": [{"focus": ["pred", "loss"], "text": "Make predictions and measure how wrong they are with the loss.", "edges": [["pred", "loss"]]}, {"focus": ["grad", "ad"], "text": "Automatic differentiation computes the gradient: which way is downhill.", "edges": [["loss", "grad"], ["ad", "grad"]]}, {"focus": ["upd"], "text": "Step downhill by the learning rate times the gradient.", "edges": [["grad", "upd"]]}, {"focus": ["w", "pred"], "text": "Updated weights give new predictions, and the loop repeats.", "edges": [["upd", "w"], ["w", "pred"]]}]}, "m1.5": {"title": "A physics-informed loss", "caption": "The model is pulled towards the data at measurement points and towards the law at collocation points.", "nodes": [{"id": "net", "label": "Model ŷ(t)", "sub": "network or basis", "x": 140, "y": 220, "w": 170, "h": 64, "sys": "economy", "detail": "Any flexible function of time: a neural network, or (in the explorer) a sum of smooth bumps."}, {"id": "dat", "label": "Data term", "sub": "Σ (ŷ − y)² at measurements", "x": 450, "y": 90, "w": 210, "h": 64, "sys": "water", "detail": "How far the model is from the few measurements we have."}, {"id": "res", "label": "Physics residual", "sub": "dŷ/dt + k ŷ at collocation pts", "x": 450, "y": 250, "w": 230, "h": 64, "sys": "energy", "detail": "How badly the model breaks the law. Computed by automatic differentiation; zero if the law is obeyed exactly."}, {"id": "col", "label": "Collocation points", "sub": "free: anywhere we like", "x": 450, "y": 420, "w": 200, "h": 64, "sys": "energy", "detail": "Times (or places) where we check the law. No measurement needed, so we can place them beyond the data."}, {"id": "tot", "label": "Total loss", "sub": "data + λ × physics", "x": 760, "y": 170, "w": 170, "h": 64, "sys": "climate", "detail": "λ, the physics weight, balances the two terms."}, {"id": "pred", "label": "Prediction", "sub": "fits data, obeys law", "x": 760, "y": 380, "w": 170, "h": 64, "sys": "land", "detail": "Accurate where we measured and sensible where we did not."}], "edges": [{"from": "net", "to": "dat", "label": ""}, {"from": "net", "to": "res", "label": ""}, {"from": "col", "to": "res", "label": "where to check"}, {"from": "dat", "to": "tot", "label": ""}, {"from": "res", "to": "tot", "label": "× λ"}, {"from": "tot", "to": "pred", "label": "minimise"}], "tour": [{"focus": ["net", "dat"], "text": "As usual, the model is compared with the data.", "edges": [["net", "dat"]]}, {"focus": ["res", "col"], "text": "New: at collocation points, we check how badly it breaks the law.", "edges": [["net", "res"], ["col", "res"]]}, {"focus": ["tot"], "text": "The total loss adds both, with a physics weight λ.", "edges": [["dat", "tot"], ["res", "tot"]]}, {"focus": ["pred"], "text": "Minimising it gives a model that fits the data and obeys the physics.", "edges": [["tot", "pred"]]}]}, "m1.6": {"title": "The bias–variance balance", "caption": "Model complexity trades missing the pattern against chasing the noise; unseen data reveal which is happening.", "nodes": [{"id": "sig", "label": "True signal", "sub": "the pattern we want", "x": 140, "y": 110, "w": 170, "h": 64, "sys": "energy", "detail": "The real relationship, for example how speed varies with density."}, {"id": "noi", "label": "Noise", "sub": "random errors", "x": 140, "y": 330, "w": 170, "h": 64, "sys": "water", "detail": "Sensor error, rounding and random fluctuations. Different every time we measure."}, {"id": "cmp", "label": "Model complexity", "sub": "simple ↔ flexible", "x": 450, "y": 220, "w": 170, "h": 64, "sys": "economy", "detail": "Polynomial degree, number of neurons, number of features."}, {"id": "und", "label": "Underfitting", "sub": "misses the pattern", "x": 760, "y": 90, "w": 170, "h": 64, "sys": "climate", "detail": "High error on training and test data. The model is too rigid (high bias)."}, {"id": "ovf", "label": "Overfitting", "sub": "learns the noise", "x": 760, "y": 260, "w": 170, "h": 64, "sys": "climate", "detail": "Low training error, high test error. The model is too flexible (high variance)."}, {"id": "val", "label": "Unseen data", "sub": "validation, test", "x": 760, "y": 430, "w": 170, "h": 64, "sys": "water", "detail": "The honest judge: data not used in fitting. Choose complexity where its error is lowest."}, {"id": "reg", "label": "Defences", "sub": "data, regularisation, physics", "x": 450, "y": 430, "w": 170, "h": 64, "sys": "land", "detail": "More data, penalties on large weights, early stopping, and physical constraints."}], "edges": [{"from": "sig", "to": "cmp", "label": ""}, {"from": "noi", "to": "cmp", "label": ""}, {"from": "cmp", "to": "und", "label": "too simple"}, {"from": "cmp", "to": "ovf", "label": "too flexible"}, {"from": "val", "to": "ovf", "label": "reveals"}, {"from": "reg", "to": "ovf", "label": "prevents", "sys": "water"}], "tour": [{"focus": ["sig", "noi"], "text": "Data are the true signal plus noise."}, {"focus": ["cmp", "und"], "text": "Too simple a model misses the pattern: underfitting.", "edges": [["cmp", "und"]]}, {"focus": ["cmp", "ovf"], "text": "Too flexible a model chases the noise: overfitting.", "edges": [["cmp", "ovf"]]}, {"focus": ["val"], "text": "Only unseen data reveal overfitting.", "edges": [["val", "ovf"]]}, {"focus": ["reg"], "text": "Defences: more data, regularisation and physics.", "edges": [["reg", "ovf"]]}]}, "m1.7": {"title": "Building and using a surrogate", "caption": "A few expensive runs train a fast model, which then answers many questions; its uncertainty guides the next run.", "nodes": [{"id": "sim", "label": "Expensive model", "sub": "hours per run", "x": 140, "y": 110, "w": 170, "h": 64, "sys": "land", "detail": "A detailed simulator: city traffic, GCAM, finite-element crash model."}, {"id": "des", "label": "Design of runs", "sub": "where to sample", "x": 140, "y": 330, "w": 170, "h": 64, "sys": "water", "detail": "Choose inputs to run: evenly spaced, Latin hypercube, or adaptive (where the surrogate is least sure)."}, {"id": "pairs", "label": "Input–output pairs", "sub": "training data", "x": 450, "y": 220, "w": 170, "h": 64, "sys": "water", "detail": "The results of the expensive runs."}, {"id": "sur", "label": "Surrogate", "sub": "RBF, GP, network", "x": 760, "y": 110, "w": 170, "h": 64, "sys": "economy", "detail": "A fast model fitted to the pairs: radial basis functions, Gaussian processes, neural networks."}, {"id": "use", "label": "Many queries", "sub": "optimise, explore, UQ", "x": 760, "y": 330, "w": 170, "h": 64, "sys": "policy", "detail": "Thousands of evaluations for design optimisation, policy exploration and uncertainty quantification."}, {"id": "unc", "label": "Surrogate uncertainty", "sub": "where to run next", "x": 450, "y": 440, "w": 170, "h": 64, "sys": "climate", "detail": "Where the surrogate is least sure, run the full model and add the result (active learning)."}], "edges": [{"from": "des", "to": "sim", "label": "run at"}, {"from": "sim", "to": "pairs", "label": ""}, {"from": "pairs", "to": "sur", "label": "train"}, {"from": "sur", "to": "use", "label": "fast"}, {"from": "sur", "to": "unc", "label": ""}, {"from": "unc", "to": "des", "label": "next run", "sys": "climate"}], "tour": [{"focus": ["sim"], "text": "Start with a model that is accurate but slow."}, {"focus": ["des", "sim", "pairs"], "text": "Run it at a few chosen inputs.", "edges": [["des", "sim"], ["sim", "pairs"]]}, {"focus": ["sur"], "text": "Fit a fast surrogate to the results.", "edges": [["pairs", "sur"]]}, {"focus": ["use"], "text": "Use the surrogate for thousands of queries.", "edges": [["sur", "use"]]}, {"focus": ["unc", "des"], "text": "Its uncertainty tells you where to run the full model next.", "edges": [["sur", "unc"], ["unc", "des"]]}]}, "m1.8": {"title": "The Physical AI loop", "caption": "Sense, estimate, decide, act; the world responds and the loop repeats many times a second.", "nodes": [{"id": "sen", "label": "Sense", "sub": "GPS, radar, cameras", "x": 140, "y": 110, "w": 170, "h": 64, "sys": "water", "detail": "Sensors measure the world, with noise, gaps and occasional failures."}, {"id": "est", "label": "Estimate", "sub": "Kalman filter, fusion", "x": 450, "y": 110, "w": 170, "h": 64, "sys": "energy", "detail": "Combine a physics prediction with measurements to estimate the true state (position, speed, queue length)."}, {"id": "dec", "label": "Decide", "sub": "plan, control, learn", "x": 760, "y": 110, "w": 170, "h": 64, "sys": "economy", "detail": "Choose an action: brake, steer, change a signal. Learned policies and model-based control both live here."}, {"id": "act", "label": "Act", "sub": "brake, steer, signal", "x": 760, "y": 330, "w": 170, "h": 64, "sys": "policy", "detail": "Actuators change the physical world: physics limits how fast this can happen."}, {"id": "wld", "label": "The world", "sub": "vehicles, roads, people", "x": 450, "y": 330, "w": 170, "h": 64, "sys": "land", "detail": "Responds to actions; other agents act too. Its physics links one moment to the next."}, {"id": "safe", "label": "Safety layer", "sub": "constraints, uncertainty", "x": 140, "y": 330, "w": 170, "h": 64, "sys": "climate", "detail": "Checks that actions respect physical limits and that estimates are certain enough to act on."}], "edges": [{"from": "sen", "to": "est", "label": "measurements"}, {"from": "est", "to": "dec", "label": "state"}, {"from": "dec", "to": "act", "label": ""}, {"from": "act", "to": "wld", "label": ""}, {"from": "wld", "to": "sen", "label": "observed"}, {"from": "safe", "to": "dec", "label": "limits", "sys": "climate"}], "tour": [{"focus": ["sen"], "text": "Sensors measure the world, imperfectly."}, {"focus": ["est"], "text": "Estimation blends physics predictions with measurements.", "edges": [["sen", "est"]]}, {"focus": ["dec", "act"], "text": "A decision is made and carried out.", "edges": [["est", "dec"], ["dec", "act"]]}, {"focus": ["wld"], "text": "The world responds and is measured again.", "edges": [["act", "wld"], ["wld", "sen"]]}, {"focus": ["safe"], "text": "A safety layer keeps actions within physical and uncertainty limits.", "edges": [["safe", "dec"]]}]}, "m2.1": {"title": "A SciML project, step by step", "caption": "Each step guards against a typical failure; skipping one usually shows up later as a model that cannot be trusted.", "nodes": [{"id": "q", "label": "1. Frame the question", "sub": "target, inputs, metric", "x": 140, "y": 90, "w": 200, "h": 64, "sys": "policy", "detail": "What exactly do you predict, from what, at what horizon, and how will you score it? Write it down before touching data."}, {"id": "d", "label": "2. Data and physics", "sub": "look, clean, list laws", "x": 140, "y": 260, "w": 200, "h": 64, "sys": "water", "detail": "Plot the data. List the equations you trust and those you do not. Note units, gaps and sensor quirks."}, {"id": "s", "label": "3. Honest split", "sub": "by time or by location", "x": 140, "y": 430, "w": 200, "h": 64, "sys": "climate", "detail": "Train, validation, test. Split time series by time and spatial data by location to avoid leakage."}, {"id": "b", "label": "4. Baseline", "sub": "physics alone, linear model", "x": 450, "y": 430, "w": 200, "h": 64, "sys": "land", "detail": "A simple model sets the bar. If a network cannot beat it, the network is not worth it."}, {"id": "m", "label": "5. Add learning + physics", "sub": "PINN, hybrid, surrogate", "x": 450, "y": 260, "w": 210, "h": 64, "sys": "economy", "detail": "Add complexity one step at a time, checking validation error after each."}, {"id": "v", "label": "6. Validate + UQ", "sub": "unseen data, uncertainty", "x": 760, "y": 260, "w": 170, "h": 64, "sys": "climate", "detail": "Test once on untouched data; report intervals, not just point errors."}, {"id": "r", "label": "7. Document + share", "sub": "code, seeds, versions", "x": 760, "y": 430, "w": 170, "h": 64, "sys": "land", "detail": "Record environment, random seeds, data versions; share code so results can be reproduced."}], "edges": [{"from": "q", "to": "d", "label": ""}, {"from": "d", "to": "s", "label": ""}, {"from": "s", "to": "b", "label": ""}, {"from": "b", "to": "m", "label": ""}, {"from": "m", "to": "v", "label": ""}, {"from": "v", "to": "r", "label": ""}, {"from": "v", "to": "m", "label": "iterate", "sys": "climate"}], "tour": [{"focus": ["q"], "text": "Start by writing the question and the success metric."}, {"focus": ["d", "s"], "text": "Look at the data, list the physics, then split honestly.", "edges": [["q", "d"], ["d", "s"]]}, {"focus": ["b"], "text": "Build a simple baseline to beat.", "edges": [["s", "b"]]}, {"focus": ["m"], "text": "Add learning and physics step by step.", "edges": [["b", "m"]]}, {"focus": ["v", "r"], "text": "Validate on unseen data, quantify uncertainty, and document.", "edges": [["m", "v"], ["v", "r"], ["v", "m"]]}]}, "m2.2": {"title": "Six steps to a working PINN", "caption": "Network, collocation points, residual by autodiff, composite loss, training, and the inverse problem.", "nodes": [{"id": "net", "label": "1. Network", "sub": "t → ŷ(t), tanh layers", "x": 140, "y": 90, "w": 170, "h": 64, "sys": "economy", "detail": "A small MLP, e.g. 1 → 32 → 32 → 1 with tanh. Smooth activations so derivatives exist."}, {"id": "col", "label": "2. Collocation points", "sub": "40 times over 0–5 s", "x": 140, "y": 260, "w": 170, "h": 64, "sys": "energy", "detail": "Where the law is enforced. Can be fixed or resampled each iteration."}, {"id": "res", "label": "3. Residual by autodiff", "sub": "dŷ/dt + k ŷ", "x": 450, "y": 90, "w": 170, "h": 64, "sys": "energy", "detail": "torch.autograd.grad(ŷ, t, create_graph=True) gives dŷ/dt; the residual should be zero."}, {"id": "loss", "label": "4. Composite loss", "sub": "data + physics + initial", "x": 450, "y": 260, "w": 170, "h": 64, "sys": "climate", "detail": "L = L_data + λ L_phys + L_ic. Initial and boundary conditions are extra terms."}, {"id": "adam", "label": "5. Train with Adam", "sub": "watch both losses", "x": 760, "y": 90, "w": 170, "h": 64, "sys": "economy", "detail": "Learning rate around 1e-3 for networks. Plot data and physics losses on a log scale."}, {"id": "inv", "label": "6. Inverse problem", "sub": "learn k from data", "x": 760, "y": 260, "w": 170, "h": 64, "sys": "water", "detail": "Declare k a trainable parameter: the PINN fits the data and finds the k that makes the law hold."}, {"id": "chk", "label": "Check", "sub": "error beyond the data", "x": 450, "y": 430, "w": 170, "h": 64, "sys": "land", "detail": "Compare with the exact solution e^(−kt) where you have no measurements."}], "edges": [{"from": "net", "to": "res", "label": ""}, {"from": "col", "to": "res", "label": "evaluate at"}, {"from": "res", "to": "loss", "label": ""}, {"from": "loss", "to": "adam", "label": "minimise"}, {"from": "adam", "to": "inv", "label": "also learns k"}, {"from": "adam", "to": "chk", "label": ""}], "tour": [{"focus": ["net", "col"], "text": "Define a smooth network and choose where to enforce the law."}, {"focus": ["res"], "text": "Automatic differentiation gives the residual dŷ/dt + kŷ.", "edges": [["net", "res"], ["col", "res"]]}, {"focus": ["loss"], "text": "Add data, physics and initial-condition terms.", "edges": [["res", "loss"]]}, {"focus": ["adam"], "text": "Train with Adam and watch both loss terms.", "edges": [["loss", "adam"]]}, {"focus": ["inv", "chk"], "text": "Make k trainable to discover it, and check beyond the data.", "edges": [["adam", "inv"], ["adam", "chk"]]}]}, "m2.3": {"title": "Two ways to solve a PDE", "caption": "A grid-based solver marches in time under a stability limit; a PINN minimises residuals at scattered points.", "nodes": [{"id": "pde", "label": "PDE + conditions", "sub": "∂u/∂t = α ∂²u/∂x²", "x": 450, "y": 80, "w": 200, "h": 64, "sys": "energy", "detail": "The equation plus boundary conditions (ends held at zero) and an initial condition (starting temperature profile)."}, {"id": "grid", "label": "Grid", "sub": "Δx, Δt", "x": 140, "y": 220, "w": 170, "h": 64, "sys": "land", "detail": "Space cut into points Δx apart; time into steps Δt."}, {"id": "fd", "label": "Finite differences", "sub": "update from neighbours", "x": 140, "y": 400, "w": 170, "h": 64, "sys": "energy", "detail": "u_i ← u_i + r (u_{i+1} − 2u_i + u_{i−1}), r = αΔt/Δx²."}, {"id": "stab", "label": "Stability", "sub": "r ≤ 0.5", "x": 450, "y": 400, "w": 170, "h": 64, "sys": "climate", "detail": "Explicit schemes blow up if r > 0.5. Implicit schemes are stable but need a linear solve each step."}, {"id": "pinn", "label": "PINN", "sub": "no grid, residual loss", "x": 760, "y": 220, "w": 170, "h": 64, "sys": "economy", "detail": "Network u(x, t); loss = residual at random (x, t) + boundary + initial terms."}, {"id": "cmp", "label": "Compare", "sub": "accuracy, cost, flexibility", "x": 760, "y": 400, "w": 170, "h": 64, "sys": "policy", "detail": "Classical: fast, accurate for forward problems. PINN: flexible geometry, data fusion, inverse problems."}], "edges": [{"from": "pde", "to": "grid", "label": ""}, {"from": "grid", "to": "fd", "label": ""}, {"from": "fd", "to": "stab", "label": "must respect"}, {"from": "pde", "to": "pinn", "label": ""}, {"from": "pinn", "to": "cmp", "label": ""}, {"from": "stab", "to": "cmp", "label": ""}], "tour": [{"focus": ["pde"], "text": "Start from the equation and its boundary and initial conditions."}, {"focus": ["grid", "fd"], "text": "The classical route: a grid, and updates from neighbours.", "edges": [["pde", "grid"], ["grid", "fd"]]}, {"focus": ["stab"], "text": "Explicit updates are stable only if r ≤ 0.5.", "edges": [["fd", "stab"]]}, {"focus": ["pinn"], "text": "The PINN route: no grid, a residual loss at scattered points.", "edges": [["pde", "pinn"]]}, {"focus": ["cmp"], "text": "Each wins in different situations.", "edges": [["pinn", "cmp"], ["stab", "cmp"]]}]}, "m2.4": {"title": "SINDy in five steps", "caption": "Measure, differentiate, build a library, regress sparsely, read the equation.", "nodes": [{"id": "meas", "label": "1. Measure", "sub": "x(t), v(t)", "x": 140, "y": 90, "w": 170, "h": 64, "sys": "water", "detail": "Time series of the state, from sensors or simulation."}, {"id": "diff", "label": "2. Differentiate", "sub": "smooth, then dv/dt", "x": 140, "y": 260, "w": 170, "h": 64, "sys": "climate", "detail": "Numerical derivatives amplify noise; smooth or use total-variation methods first."}, {"id": "lib", "label": "3. Library Θ", "sub": "1, x, v, x², xv, v², x³", "x": 450, "y": 90, "w": 200, "h": 64, "sys": "energy", "detail": "Candidate terms that might appear in the law. Physics knowledge guides the choice."}, {"id": "reg", "label": "4. Sparse regression", "sub": "fit, threshold, refit", "x": 450, "y": 260, "w": 170, "h": 64, "sys": "economy", "detail": "Least squares, then zero coefficients below a threshold λ and refit (STLSQ)."}, {"id": "eq", "label": "5. Read the equation", "sub": "dv/dt = −4x − 0.3v", "x": 760, "y": 175, "w": 190, "h": 64, "sys": "energy", "detail": "A short, interpretable law that can be checked, simulated and extrapolated."}, {"id": "node", "label": "Alternative: neural ODE", "sub": "dx/dt = network(x)", "x": 450, "y": 430, "w": 210, "h": 64, "sys": "economy", "detail": "Learn the right-hand side with a network and integrate it with an ODE solver. Flexible, not readable."}], "edges": [{"from": "meas", "to": "diff", "label": ""}, {"from": "diff", "to": "reg", "label": "targets"}, {"from": "meas", "to": "lib", "label": "evaluate"}, {"from": "lib", "to": "reg", "label": "features"}, {"from": "reg", "to": "eq", "label": ""}, {"from": "meas", "to": "node", "label": "or"}], "tour": [{"focus": ["meas", "diff"], "text": "Measure the state and estimate its derivatives, smoothing noise first.", "edges": [["meas", "diff"]]}, {"focus": ["lib"], "text": "Build a library of candidate terms.", "edges": [["meas", "lib"]]}, {"focus": ["reg"], "text": "Fit all terms, cut the small ones, refit.", "edges": [["diff", "reg"], ["lib", "reg"]]}, {"focus": ["eq"], "text": "What remains is a readable equation.", "edges": [["reg", "eq"]]}, {"focus": ["node"], "text": "A neural ODE learns the right-hand side with a network instead.", "edges": [["meas", "node"]]}]}, "m2.5": {"title": "Learning a solution operator", "caption": "A classical solver makes example pairs; a neural operator learns the map; new inputs are solved instantly.", "nodes": [{"id": "f", "label": "Input function f(x)", "sub": "source, demand, coefficient", "x": 140, "y": 110, "w": 200, "h": 64, "sys": "water", "detail": "A whole function: a heat source, a demand profile, a road's capacity along its length."}, {"id": "sol", "label": "Classical solver", "sub": "makes training pairs", "x": 140, "y": 330, "w": 170, "h": 64, "sys": "energy", "detail": "Solve the PDE for many random inputs to build a data set of (f, u) pairs. Expensive, but done once."}, {"id": "br", "label": "Branch net", "sub": "reads f at sensors", "x": 450, "y": 110, "w": 170, "h": 64, "sys": "economy", "detail": "Encodes the input function sampled at m fixed sensor points into p numbers."}, {"id": "tr", "label": "Trunk net", "sub": "reads location x", "x": 450, "y": 330, "w": 170, "h": 64, "sys": "economy", "detail": "Encodes the query location into p numbers."}, {"id": "u", "label": "Output u(x)", "sub": "branch · trunk", "x": 760, "y": 220, "w": 170, "h": 64, "sys": "land", "detail": "DeepONet output: dot product of branch and trunk vectors. Any x can be queried."}, {"id": "cov", "label": "Coverage of inputs", "sub": "train like you test", "x": 450, "y": 460, "w": 170, "h": 64, "sys": "climate", "detail": "If new inputs look unlike the training inputs, predictions can be badly wrong."}], "edges": [{"from": "f", "to": "sol", "label": ""}, {"from": "sol", "to": "br", "label": "pairs"}, {"from": "f", "to": "br", "label": ""}, {"from": "tr", "to": "u", "label": ""}, {"from": "br", "to": "u", "label": "dot product"}, {"from": "cov", "to": "br", "label": "limits", "sys": "climate"}], "tour": [{"focus": ["f", "sol"], "text": "Generate many input functions and solve each with a classical solver.", "edges": [["f", "sol"]]}, {"focus": ["br"], "text": "The branch net encodes the input function.", "edges": [["f", "br"], ["sol", "br"]]}, {"focus": ["tr"], "text": "The trunk net encodes where we want the answer."}, {"focus": ["u"], "text": "Their dot product gives the solution at that point.", "edges": [["br", "u"], ["tr", "u"]]}, {"focus": ["cov"], "text": "It only works for inputs like those seen in training.", "edges": [["cov", "br"]]}]}, "m2.6": {"title": "From prior to calibrated prediction", "caption": "A kernel defines plausible curves; data narrow them; the length scale is tuned; calibration is checked.", "nodes": [{"id": "pri", "label": "Prior", "sub": "cloud of smooth curves", "x": 140, "y": 110, "w": 170, "h": 64, "sys": "economy", "detail": "Before data: a Gaussian process with mean zero and a kernel k(x, x′)."}, {"id": "ker", "label": "Kernel", "sub": "similarity, length scale ℓ", "x": 140, "y": 330, "w": 170, "h": 64, "sys": "energy", "detail": "Squared exponential: k = σ² exp(−(x − x′)²/(2ℓ²)). ℓ sets how fast similarity fades. Kernels can encode physics (periodic, smooth, linear)."}, {"id": "obs", "label": "Observations", "sub": "with noise σₙ", "x": 450, "y": 110, "w": 170, "h": 64, "sys": "water", "detail": "Each data point pins the curves near it, up to the noise level."}, {"id": "post", "label": "Posterior", "sub": "mean + band", "x": 450, "y": 330, "w": 170, "h": 64, "sys": "land", "detail": "Closed-form formulas give the mean and variance at any x. Bands widen away from data."}, {"id": "ml", "label": "Marginal likelihood", "sub": "tune ℓ, σ", "x": 760, "y": 110, "w": 170, "h": 64, "sys": "economy", "detail": "Pick hyperparameters that make the observed data most probable."}, {"id": "cal", "label": "Calibration", "sub": "95% band, 95% coverage", "x": 760, "y": 330, "w": 170, "h": 64, "sys": "climate", "detail": "Check on held-out data that bands contain the truth as often as claimed."}], "edges": [{"from": "pri", "to": "post", "label": ""}, {"from": "ker", "to": "pri", "label": "defines"}, {"from": "obs", "to": "post", "label": "conditions"}, {"from": "ml", "to": "ker", "label": "tunes"}, {"from": "post", "to": "cal", "label": "check"}], "tour": [{"focus": ["pri", "ker"], "text": "A kernel defines which curves are plausible before data.", "edges": [["ker", "pri"]]}, {"focus": ["obs", "post"], "text": "Data pin the curves: the posterior mean and band.", "edges": [["pri", "post"], ["obs", "post"]]}, {"focus": ["ml"], "text": "Maximum likelihood tunes the length scale and noise.", "edges": [["ml", "ker"]]}, {"focus": ["cal"], "text": "Finally check calibration: do 95% bands cover 95%?", "edges": [["post", "cal"]]}]}, "m2.7": {"title": "Patterns of hybrid modelling", "caption": "Keep the physics where it is trusted; learn only the part it misses.", "nodes": [{"id": "phy", "label": "Physics model", "sub": "Greenshields, IDM, LWR", "x": 140, "y": 110, "w": 170, "h": 64, "sys": "energy", "detail": "A trusted but imperfect model: right structure, simplified details."}, {"id": "res", "label": "Residual learning", "sub": "y = physics + ML(x)", "x": 450, "y": 110, "w": 170, "h": 64, "sys": "economy", "detail": "Learn the difference between data and physics. The most common and simplest hybrid."}, {"id": "par", "label": "Parameter learning", "sub": "ML predicts parameters", "x": 450, "y": 270, "w": 170, "h": 64, "sys": "economy", "detail": "A network predicts physical parameters (e.g. capacity by weather and time), and the physics model runs with them."}, {"id": "clo", "label": "Closure learning", "sub": "ML for missing terms", "x": 450, "y": 430, "w": 170, "h": 64, "sys": "economy", "detail": "Learn terms the physics cannot resolve, inside the equation (e.g. lane-changing in a traffic model)."}, {"id": "dat", "label": "Data", "sub": "only where measured", "x": 140, "y": 330, "w": 170, "h": 64, "sys": "water", "detail": "Sparse and limited to the conditions observed."}, {"id": "out", "label": "Hybrid prediction", "sub": "accurate + safe beyond data", "x": 760, "y": 270, "w": 170, "h": 64, "sys": "land", "detail": "Fits the data and falls back on the physics where data are missing."}], "edges": [{"from": "phy", "to": "res", "label": ""}, {"from": "dat", "to": "res", "label": "residuals"}, {"from": "phy", "to": "par", "label": ""}, {"from": "phy", "to": "clo", "label": ""}, {"from": "res", "to": "out", "label": ""}, {"from": "par", "to": "out", "label": ""}, {"from": "clo", "to": "out", "label": ""}], "tour": [{"focus": ["phy", "dat"], "text": "Start with an imperfect physics model and some data."}, {"focus": ["res"], "text": "Residual learning: learn only the gap between them.", "edges": [["phy", "res"], ["dat", "res"]]}, {"focus": ["par"], "text": "Or let a network predict the physics model's parameters.", "edges": [["phy", "par"]]}, {"focus": ["clo"], "text": "Or learn missing terms inside the equation.", "edges": [["phy", "clo"]]}, {"focus": ["out"], "text": "All three keep the physics' good behaviour beyond the data.", "edges": [["res", "out"], ["par", "out"], ["clo", "out"]]}]}, "m2.8": {"title": "From trained model to trusted service", "caption": "Validation, physical checks and calibrated uncertainty come before deployment; monitoring and fallbacks come after.", "nodes": [{"id": "mod", "label": "Trained model", "sub": "low training loss", "x": 140, "y": 110, "w": 170, "h": 64, "sys": "economy", "detail": "A good start, not an end."}, {"id": "val", "label": "Unseen-condition tests", "sub": "new weeks, sites, events", "x": 450, "y": 110, "w": 200, "h": 64, "sys": "water", "detail": "Out-of-distribution tests: holidays, incidents, other cities, future years."}, {"id": "phy", "label": "Physical checks", "sub": "conservation, bounds", "x": 760, "y": 110, "w": 170, "h": 64, "sys": "energy", "detail": "Vehicles conserved, speeds ≥ 0, flows ≤ capacity, energy balances close."}, {"id": "uq", "label": "Calibrated intervals", "sub": "conformal, Bayesian", "x": 760, "y": 300, "w": 170, "h": 64, "sys": "climate", "detail": "Intervals whose coverage is checked on held-out data."}, {"id": "dep", "label": "Deployment", "sub": "latency, edge, cloud", "x": 450, "y": 300, "w": 170, "h": 64, "sys": "policy", "detail": "Fast enough for its use: milliseconds in a vehicle, minutes for planning."}, {"id": "mon", "label": "Monitoring + fallback", "sub": "drift, retrain, safe mode", "x": 140, "y": 300, "w": 170, "h": 64, "sys": "climate", "detail": "Watch input and error drift; retrain on schedule; fall back to physics when unsure."}, {"id": "doc", "label": "Model card", "sub": "scope, limits, data", "x": 450, "y": 460, "w": 170, "h": 64, "sys": "land", "detail": "Document what it is for, what data it saw, and where it must not be used."}], "edges": [{"from": "mod", "to": "val", "label": ""}, {"from": "val", "to": "phy", "label": ""}, {"from": "phy", "to": "uq", "label": ""}, {"from": "uq", "to": "dep", "label": ""}, {"from": "dep", "to": "mon", "label": ""}, {"from": "mon", "to": "mod", "label": "retrain", "sys": "climate"}, {"from": "dep", "to": "doc", "label": "documented"}], "tour": [{"focus": ["mod", "val"], "text": "Test on conditions the model has never seen.", "edges": [["mod", "val"]]}, {"focus": ["phy"], "text": "Check physical consistency.", "edges": [["val", "phy"]]}, {"focus": ["uq"], "text": "Attach intervals whose coverage you have checked.", "edges": [["phy", "uq"]]}, {"focus": ["dep", "doc"], "text": "Deploy with a model card describing scope and limits.", "edges": [["uq", "dep"], ["dep", "doc"]]}, {"focus": ["mon"], "text": "Monitor for drift, retrain, and fall back safely when unsure.", "edges": [["dep", "mon"], ["mon", "mod"]]}]}, "m3.1": {"title": "Estimating traffic everywhere from data somewhere", "caption": "Sparse detectors and probes plus a traffic-flow model give a full space–time picture of the road.", "nodes": [{"id": "det", "label": "Loop detectors", "sub": "flow, speed at points", "x": 140, "y": 90, "w": 170, "h": 64, "sys": "water", "detail": "Fixed sensors, typically 0.5 to 2 km apart on motorways; noisy and sometimes broken."}, {"id": "prb", "label": "Probe vehicles", "sub": "GPS traces, connected cars", "x": 140, "y": 270, "w": 170, "h": 64, "sys": "water", "detail": "Scattered samples along the road from phones, fleets and connected vehicles."}, {"id": "lwr", "label": "LWR model", "sub": "∂ρ/∂t + ∂q(ρ)/∂x = 0", "x": 450, "y": 90, "w": 190, "h": 64, "sys": "energy", "detail": "Conservation of vehicles plus a fundamental diagram q(ρ). Jams travel as shock waves."}, {"id": "fus", "label": "Data fusion", "sub": "nudging, Kalman, PIDL", "x": 450, "y": 270, "w": 170, "h": 64, "sys": "economy", "detail": "Correct the model towards data (nudging, Kalman filters) or train a network with LWR residuals (physics-informed deep learning)."}, {"id": "map", "label": "Space–time map", "sub": "density everywhere", "x": 760, "y": 180, "w": 170, "h": 64, "sys": "land", "detail": "A full picture of density, speed and flow along the road over time."}, {"id": "use", "label": "Operations", "sub": "ramp metering, alerts", "x": 760, "y": 380, "w": 170, "h": 64, "sys": "policy", "detail": "Feeds control (ramp metering, variable speed limits), traveller information and incident detection."}, {"id": "int", "label": "Interpolation", "sub": "straight lines", "x": 450, "y": 440, "w": 170, "h": 64, "sys": "climate", "detail": "Ignores physics; blurs or misses shock waves between detectors."}], "edges": [{"from": "det", "to": "fus", "label": ""}, {"from": "prb", "to": "fus", "label": ""}, {"from": "lwr", "to": "fus", "label": "physics"}, {"from": "fus", "to": "map", "label": ""}, {"from": "map", "to": "use", "label": ""}, {"from": "det", "to": "int", "label": "or"}, {"from": "int", "to": "map", "label": "blurred", "sys": "climate"}], "tour": [{"focus": ["det", "prb"], "text": "Data arrive from fixed detectors and moving probes."}, {"focus": ["lwr"], "text": "The LWR model knows that vehicles are conserved and jams move as waves."}, {"focus": ["fus"], "text": "Fusion combines both: the model fills gaps, the data keep it honest.", "edges": [["det", "fus"], ["prb", "fus"], ["lwr", "fus"]]}, {"focus": ["map", "use"], "text": "The result is a full space–time map for operations.", "edges": [["fus", "map"], ["map", "use"]]}, {"focus": ["int"], "text": "Interpolation alone blurs the jams.", "edges": [["det", "int"], ["int", "map"]]}]}, "m3.2": {"title": "A braking wave along a platoon", "caption": "Each vehicle's controller turns perception of the vehicle ahead into acceleration; delays and gains decide whether disturbances grow.", "nodes": [{"id": "lead", "label": "Lead vehicle", "sub": "brakes hard for 4 s", "x": 140, "y": 110, "w": 170, "h": 64, "sys": "land", "detail": "The disturbance: a sudden slowdown at the front of the line."}, {"id": "sense", "label": "Perception", "sub": "eyes, radar, V2V", "x": 450, "y": 110, "w": 170, "h": 64, "sys": "water", "detail": "Humans see the gap and brake lights with delay; radar measures gap and relative speed; V2V radio sends the leader's acceleration instantly."}, {"id": "ctrl", "label": "Controller", "sub": "IDM, ACC, CACC", "x": 760, "y": 110, "w": 170, "h": 64, "sys": "energy", "detail": "IDM: a = a_max[1 − (v/v0)⁴ − (s*/s)²], s* = s0 + vT + vΔv/(2√(ab)). ACC and CACC are automated versions."}, {"id": "act", "label": "Acceleration", "sub": "brake or throttle", "x": 760, "y": 330, "w": 170, "h": 64, "sys": "policy", "detail": "Limited by tyres and comfort: about −9 to +3 m/s²."}, {"id": "next", "label": "Next vehicle", "sub": "sees the result", "x": 450, "y": 330, "w": 170, "h": 64, "sys": "land", "detail": "Each follower becomes the leader of the next: the disturbance passes down the line."}, {"id": "ss", "label": "String stability", "sub": "does the wave shrink?", "x": 140, "y": 330, "w": 170, "h": 64, "sys": "climate", "detail": "If speed dips shrink down the platoon, it is string stable; if they grow, phantom jams and rear-end risk follow."}, {"id": "ml", "label": "Learned residual", "sub": "IDM + network", "x": 450, "y": 460, "w": 170, "h": 64, "sys": "economy", "detail": "A network trained on trajectories corrects the IDM's acceleration; physics keeps it safe and interpretable."}], "edges": [{"from": "lead", "to": "sense", "label": ""}, {"from": "sense", "to": "ctrl", "label": ""}, {"from": "ctrl", "to": "act", "label": ""}, {"from": "act", "to": "next", "label": ""}, {"from": "next", "to": "ss", "label": ""}, {"from": "ml", "to": "ctrl", "label": "corrects", "sys": "water"}], "tour": [{"focus": ["lead"], "text": "The lead car brakes suddenly."}, {"focus": ["sense", "ctrl"], "text": "The follower perceives it, with or without delay, and its controller chooses an acceleration.", "edges": [["lead", "sense"], ["sense", "ctrl"]]}, {"focus": ["act", "next"], "text": "That acceleration becomes the disturbance for the next car.", "edges": [["ctrl", "act"], ["act", "next"]]}, {"focus": ["ss"], "text": "If dips grow down the line, the platoon is string unstable.", "edges": [["next", "ss"]]}, {"focus": ["ml"], "text": "Learned residuals can refine the physics model.", "edges": [["ml", "ctrl"]]}]}, "m3.3": {"title": "From video to risk", "caption": "Vision extracts trajectories, physics measures conflicts, statistics links conflicts to crash risk.", "nodes": [{"id": "vid", "label": "Video and sensors", "sub": "cameras, drones, lidar", "x": 140, "y": 110, "w": 170, "h": 64, "sys": "water", "detail": "Hours of footage from junctions and roads; drones give a top-down view."}, {"id": "cv", "label": "Computer vision", "sub": "detect and track", "x": 450, "y": 110, "w": 170, "h": 64, "sys": "economy", "detail": "Object detectors (e.g. YOLO) and trackers turn pixels into vehicle and pedestrian trajectories."}, {"id": "ssm", "label": "Surrogate measures", "sub": "TTC, PET, DRAC", "x": 760, "y": 110, "w": 170, "h": 64, "sys": "energy", "detail": "TTC = gap/closing speed; post-encroachment time (PET) at crossings; DRAC = closing speed²/(2 gap)."}, {"id": "conf", "label": "Conflicts", "sub": "TTC < 1.5 s", "x": 760, "y": 330, "w": 170, "h": 64, "sys": "climate", "detail": "Events below a threshold. Far more frequent than crashes, so observable in days."}, {"id": "evt", "label": "Rare-event model", "sub": "extreme value theory", "x": 450, "y": 330, "w": 170, "h": 64, "sys": "economy", "detail": "Fit the tail of the conflict-severity distribution to estimate crash probability (e.g. Songchitruksa and Tarko 2006)."}, {"id": "dec", "label": "Safety decisions", "sub": "design, signals, speed", "x": 140, "y": 330, "w": 170, "h": 64, "sys": "policy", "detail": "Compare designs or interventions before crashes accumulate."}], "edges": [{"from": "vid", "to": "cv", "label": ""}, {"from": "cv", "to": "ssm", "label": "trajectories"}, {"from": "ssm", "to": "conf", "label": ""}, {"from": "conf", "to": "evt", "label": ""}, {"from": "evt", "to": "dec", "label": "crash risk"}], "tour": [{"focus": ["vid", "cv"], "text": "Cameras record traffic; computer vision extracts trajectories.", "edges": [["vid", "cv"]]}, {"focus": ["ssm"], "text": "Physics turns trajectories into surrogate safety measures.", "edges": [["cv", "ssm"]]}, {"focus": ["conf"], "text": "Events below a threshold are counted as conflicts.", "edges": [["ssm", "conf"]]}, {"focus": ["evt"], "text": "Rare-event statistics link conflicts to crash risk.", "edges": [["conf", "evt"]]}, {"focus": ["dec"], "text": "Engineers act before crashes accumulate.", "edges": [["evt", "dec"]]}]}, "m3.4": {"title": "From driving to emissions", "caption": "Speed profiles give tractive power by physics; powertrain models and learned corrections give energy; networks and policies scale it up.", "nodes": [{"id": "cyc", "label": "Driving cycle", "sub": "speed over time", "x": 140, "y": 110, "w": 170, "h": 64, "sys": "water", "detail": "From GPS traces, traffic simulation or standard test cycles."}, {"id": "rl", "label": "Road-load equation", "sub": "P = m v (a + g sinθ) + ...", "x": 450, "y": 110, "w": 210, "h": 64, "sys": "energy", "detail": "Inertia, grade, rolling resistance (m g C_r v) and drag (½ ρ C_d A v³)."}, {"id": "pt", "label": "Powertrain", "sub": "engine, battery, regen", "x": 760, "y": 110, "w": 170, "h": 64, "sys": "energy", "detail": "Petrol ~25% efficient, no regen; electric ~85% with partial regenerative braking."}, {"id": "ml", "label": "Learned correction", "sub": "engine maps, traffic", "x": 760, "y": 300, "w": 170, "h": 64, "sys": "economy", "detail": "Fit the residual between physics and measured fuel or energy: efficiency at different loads, cold starts, auxiliaries."}, {"id": "em", "label": "Energy and CO₂", "sub": "per km, per trip", "x": 450, "y": 300, "w": 170, "h": 64, "sys": "climate", "detail": "Petrol ~73 g CO₂ per MJ of fuel; electricity depends on the grid mix."}, {"id": "net", "label": "Network and policy", "sub": "fleets, scenarios", "x": 140, "y": 300, "w": 170, "h": 64, "sys": "policy", "detail": "Scale to corridors and cities with traffic models; feed into national and global models such as GCAM (module 3.5)."}], "edges": [{"from": "cyc", "to": "rl", "label": ""}, {"from": "rl", "to": "pt", "label": "power"}, {"from": "pt", "to": "em", "label": ""}, {"from": "ml", "to": "em", "label": "corrects"}, {"from": "em", "to": "net", "label": ""}], "tour": [{"focus": ["cyc", "rl"], "text": "A speed profile and the road-load equation give the power at the wheels.", "edges": [["cyc", "rl"]]}, {"focus": ["pt"], "text": "The powertrain turns this into fuel or battery energy.", "edges": [["rl", "pt"]]}, {"focus": ["ml"], "text": "A learned correction fixes what the simple physics misses.", "edges": [["ml", "em"]]}, {"focus": ["em"], "text": "The result: energy and CO₂ per kilometre.", "edges": [["pt", "em"]]}, {"focus": ["net"], "text": "Scaled up, it informs network and climate policy.", "edges": [["em", "net"]]}]}, "m3.5": {"title": "Emulating an integrated assessment model", "caption": "A few expensive GCAM runs train an emulator; its uncertainty chooses the next run; policy questions are answered at emulator speed.", "nodes": [{"id": "gcam", "label": "GCAM", "sub": "energy, land, water, economy, climate", "x": 140, "y": 110, "w": 210, "h": 64, "sys": "land", "detail": "A global, regional, market-equilibrium model run in 5-year steps to 2100 (Calvin et al. 2019). Hours per scenario."}, {"id": "des", "label": "Design of runs", "sub": "carbon price, tech costs", "x": 140, "y": 330, "w": 170, "h": 64, "sys": "water", "detail": "Choose input combinations: space-filling designs over policy and technology parameters."}, {"id": "out", "label": "Outputs", "sub": "transport CO₂, energy use", "x": 450, "y": 110, "w": 170, "h": 64, "sys": "water", "detail": "Quantities of interest, e.g. transport CO₂ in 2050, electricity demand, land use."}, {"id": "emu", "label": "Emulator", "sub": "Gaussian process", "x": 450, "y": 330, "w": 170, "h": 64, "sys": "economy", "detail": "Fast statistical stand-in with uncertainty; neural networks for many outputs."}, {"id": "al", "label": "Active learning", "sub": "run where unsure", "x": 760, "y": 330, "w": 170, "h": 64, "sys": "climate", "detail": "Choose the next GCAM run where emulator uncertainty is largest."}, {"id": "pol", "label": "Policy analysis", "sub": "thousands of scenarios", "x": 760, "y": 110, "w": 170, "h": 64, "sys": "policy", "detail": "Explore policy space, sensitivity, uncertainty and robust strategies at emulator speed."}], "edges": [{"from": "des", "to": "gcam", "label": "run"}, {"from": "gcam", "to": "out", "label": ""}, {"from": "out", "to": "emu", "label": "train"}, {"from": "emu", "to": "pol", "label": "fast"}, {"from": "emu", "to": "al", "label": ""}, {"from": "al", "to": "des", "label": "next run", "sys": "climate"}], "tour": [{"focus": ["gcam"], "text": "GCAM couples energy, land, water, economy and climate, but runs slowly."}, {"focus": ["des", "out"], "text": "Run it at a few carefully chosen inputs.", "edges": [["des", "gcam"], ["gcam", "out"]]}, {"focus": ["emu"], "text": "Train a fast emulator on the results.", "edges": [["out", "emu"]]}, {"focus": ["al"], "text": "Its uncertainty shows where to run GCAM next.", "edges": [["emu", "al"], ["al", "des"]]}, {"focus": ["pol"], "text": "Then explore thousands of policy scenarios quickly.", "edges": [["emu", "pol"]]}]}, "m3.6": {"title": "SciML for crowd safety", "caption": "Data from comfortable densities, physics for dangerous ones, and monitoring that respects people.", "nodes": [{"id": "traj", "label": "Trajectory data", "sub": "experiments, video", "x": 140, "y": 110, "w": 170, "h": 64, "sys": "water", "detail": "Controlled experiments (e.g. Jülich), video-derived tracks, counts. Mostly at moderate densities."}, {"id": "fd", "label": "Physics-shaped laws", "sub": "Weidmann, Fruin", "x": 450, "y": 110, "w": 170, "h": 64, "sys": "energy", "detail": "Fundamental diagrams with speed → 0 at jam density; levels of service. Few parameters, safe extrapolation."}, {"id": "sfm", "label": "Learned model parameters", "sub": "social force, CA, routes", "x": 760, "y": 110, "w": 200, "h": 64, "sys": "economy", "detail": "Fit social-force strengths, desired speeds and route-choice weights to trajectories; or learn residual forces with networks."}, {"id": "pinn", "label": "Physics-informed density fields", "sub": "conservation + data", "x": 760, "y": 330, "w": 210, "h": 64, "sys": "economy", "detail": "Networks for density and velocity constrained by pedestrian continuity equations."}, {"id": "mon", "label": "Monitoring", "sub": "counting, pressure maps", "x": 450, "y": 330, "w": 170, "h": 64, "sys": "policy", "detail": "Camera-based crowd counting and crowd pressure maps for control rooms."}, {"id": "eth", "label": "Privacy and ethics", "sub": "aggregate, anonymise", "x": 140, "y": 330, "w": 170, "h": 64, "sys": "climate", "detail": "Use aggregate densities, avoid identifying individuals, document purpose and retention."}], "edges": [{"from": "traj", "to": "fd", "label": "calibrate"}, {"from": "traj", "to": "sfm", "label": "fit"}, {"from": "fd", "to": "pinn", "label": "constrains"}, {"from": "sfm", "to": "pinn", "label": ""}, {"from": "pinn", "to": "mon", "label": ""}, {"from": "eth", "to": "mon", "label": "governs", "sys": "climate"}], "tour": [{"focus": ["traj"], "text": "Data come mostly from comfortable densities."}, {"focus": ["fd"], "text": "Physics-shaped laws extrapolate safely to dangerous densities.", "edges": [["traj", "fd"]]}, {"focus": ["sfm"], "text": "Pedestrian model parameters can be learned from trajectories.", "edges": [["traj", "sfm"]]}, {"focus": ["pinn", "mon"], "text": "Physics-informed fields support real-time monitoring.", "edges": [["fd", "pinn"], ["sfm", "pinn"], ["pinn", "mon"]]}, {"focus": ["eth"], "text": "Monitoring must respect privacy.", "edges": [["eth", "mon"]]}]}, "m3.7": {"title": "A transport digital twin", "caption": "Live data correct the model; the corrected model forecasts and tests actions; decisions change the real system.", "nodes": [{"id": "real", "label": "Real system", "sub": "roads, signals, vehicles", "x": 140, "y": 110, "w": 170, "h": 64, "sys": "land", "detail": "The physical network with its traffic, incidents and weather."}, {"id": "sens", "label": "Live data", "sub": "detectors, probes, cameras", "x": 140, "y": 330, "w": 170, "h": 64, "sys": "water", "detail": "Streams of counts, speeds, trajectories and events; with noise, delays and failures."}, {"id": "mod", "label": "Physics model", "sub": "queue, LWR, simulation", "x": 450, "y": 110, "w": 170, "h": 64, "sys": "energy", "detail": "Traffic-flow or queue model that predicts how the state evolves."}, {"id": "da", "label": "Data assimilation", "sub": "predict, then correct", "x": 450, "y": 330, "w": 170, "h": 64, "sys": "economy", "detail": "Kalman-type correction keeps the model state close to observations."}, {"id": "fc", "label": "Forecast and what-if", "sub": "next 15 minutes, plans", "x": 760, "y": 110, "w": 170, "h": 64, "sys": "policy", "detail": "Forecast queues and travel times; test signal plans or diversions safely in the twin."}, {"id": "act", "label": "Decisions", "sub": "signals, ramp meters, info", "x": 760, "y": 330, "w": 170, "h": 64, "sys": "policy", "detail": "Approved actions are sent to the real system; their effects are measured again."}], "edges": [{"from": "real", "to": "sens", "label": "measured"}, {"from": "sens", "to": "da", "label": ""}, {"from": "mod", "to": "da", "label": "prediction"}, {"from": "da", "to": "fc", "label": "current state"}, {"from": "fc", "to": "act", "label": ""}, {"from": "act", "to": "real", "label": "changes"}], "tour": [{"focus": ["real", "sens"], "text": "The real system is measured continuously.", "edges": [["real", "sens"]]}, {"focus": ["mod"], "text": "A physics model predicts the next state."}, {"focus": ["da"], "text": "Data assimilation corrects the prediction with live data.", "edges": [["sens", "da"], ["mod", "da"]]}, {"focus": ["fc"], "text": "The twin forecasts and tests actions safely.", "edges": [["da", "fc"]]}, {"focus": ["act"], "text": "Decisions return to the real system, closing the loop.", "edges": [["fc", "act"], ["act", "real"]]}]}, "m3.8": {"title": "Open questions and good practice", "caption": "Five research fronts, and the reporting habits that make SciML results trustworthy.", "nodes": [{"id": "fm", "label": "Foundation models", "sub": "pretrained on physics", "x": 140, "y": 90, "w": 170, "h": 64, "sys": "economy", "detail": "Large models pretrained on many simulations and sensors, fine-tuned for new tasks (e.g. weather foundation models)."}, {"id": "wm", "label": "World models", "sub": "learned simulators", "x": 140, "y": 260, "w": 170, "h": 64, "sys": "economy", "detail": "Generative models of traffic scenes used to train and test automated vehicles."}, {"id": "ver", "label": "Verification", "sub": "safe learned control", "x": 140, "y": 430, "w": 170, "h": 64, "sys": "climate", "detail": "Proving learned controllers stay within safe limits, including unseen situations."}, {"id": "rare", "label": "Rare events", "sub": "crashes, crushes, extremes", "x": 450, "y": 430, "w": 170, "h": 64, "sys": "climate", "detail": "Learning about what is almost never observed: physics, simulation and extreme value methods."}, {"id": "fair", "label": "Fairness and transfer", "sub": "who benefits?", "x": 760, "y": 430, "w": 170, "h": 64, "sys": "policy", "detail": "Models trained in rich, data-dense places may fail or harm elsewhere."}, {"id": "you", "label": "Your study", "sub": "question, data, physics", "x": 450, "y": 220, "w": 170, "h": 64, "sys": "land", "detail": "A research question that uses SciML for a transport problem."}, {"id": "rep", "label": "Honest reporting", "sub": "baselines, UQ, limits", "x": 760, "y": 220, "w": 170, "h": 64, "sys": "climate", "detail": "Strong baselines, held-out tests, uncertainty, clear limits, open code and data."}], "edges": [{"from": "fm", "to": "you", "label": ""}, {"from": "wm", "to": "you", "label": ""}, {"from": "ver", "to": "you", "label": ""}, {"from": "rare", "to": "you", "label": ""}, {"from": "fair", "to": "you", "label": ""}, {"from": "you", "to": "rep", "label": "write up"}], "tour": [{"focus": ["fm", "wm"], "text": "Two fronts: foundation models and learned world models."}, {"focus": ["ver", "rare"], "text": "Two more: verifying learned control and learning about rare events."}, {"focus": ["fair"], "text": "And fairness: models must work for everyone they affect."}, {"focus": ["you"], "text": "Your study draws on these fronts.", "edges": [["fm", "you"], ["wm", "you"], ["ver", "you"], ["rare", "you"], ["fair", "you"]]}, {"focus": ["rep"], "text": "Report it honestly.", "edges": [["you", "rep"]]}]}};
